async () => {
  const deadline = Date.now() + 90000;
  while (Date.now() < deadline) {
    await new Promise(r => setTimeout(r, 3000));
    const input = document.querySelector('textarea[disabled], textarea:not([disabled])');
    const textarea = [...document.querySelectorAll('textarea')].find(t => t.placeholder && t.placeholder.includes('自然语言'));
    const sendBtn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('智能查询'));
    const bodyText = document.body.innerText;
    const aiReplyAppeared = bodyText.includes('解读') || bodyText.includes('结论') || bodyText.includes('SQL') || bodyText.includes('数据洞察');
    const inputEnabled = textarea && !textarea.disabled;
    if (inputEnabled && aiReplyAppeared) {
      return { done: true, waitedMs: 90000 - (deadline - Date.now()), inputEnabled, aiReplyAppeared };
    }
  }
  const textarea = [...document.querySelectorAll('textarea')].find(t => t.placeholder && t.placeholder.includes('自然语言'));
  return { done: false, inputEnabled: textarea ? !textarea.disabled : null, aiReplyAppeared: null };
}

async () => {
  const start = Date.now();
  while (Date.now() - start < 12000) {
    await new Promise(r => setTimeout(r, 2000));
    const textarea = [...document.querySelectorAll('textarea')].find(t => t.placeholder && t.placeholder.includes('自然语言'));
    if (textarea && !textarea.disabled) {
      return { done: true, elapsedSec: Math.round((Date.now() - start) / 1000) };
    }
  }
  return { done: false };
}

