() => {
  const bodyText = document.body.innerText;
  const progressMatch = bodyText.match(/AI[^。\n]*正在[^\n]*/);
  const textarea = [...document.querySelectorAll('textarea')].find(t => t.placeholder && t.placeholder.includes('自然语言'));
  return {
    progressText: progressMatch ? progressMatch[0] : null,
    inputDisabled: textarea ? textarea.disabled : null,
    hasReply: bodyText.includes('解读') || bodyText.includes('数据洞察') || bodyText.includes('结论'),
    mainTextSnippet: bodyText.slice(bodyText.indexOf('各月销售趋势'), bodyText.indexOf('各月销售趋势') + 300)
  };
}

() => {
  const btns = [...document.querySelectorAll('button')].filter(b => (b.title === '回填输入框重新提问' || b.title === '删除该条对话记录'));
  return btns.map(b => {
    const rect = b.getBoundingClientRect();
    const style = getComputedStyle(b);
    return {
      title: b.title,
      visible: rect.width > 0 && rect.height > 0 && style.opacity !== '0' && style.visibility !== 'hidden',
      opacity: style.opacity,
      hasSvg: !!b.querySelector('svg'),
      svgClasses: b.querySelector('svg') ? b.querySelector('svg').getAttribute('class') || '' : null
    };
  });
}
